import React, { useState, useEffect } from 'react';
import { 
  Bus, 
  PlusCircle, 
  Users, 
  Ticket, 
  TrendingUp, 
  User as UserIcon, 
  CreditCard,
  Trash2,
  X,
  Shield,
  Key,
  DollarSign,
  Camera,
  Lock,
  Phone,
  Mail,
  UserCheck,
  History,
  Image as ImageIcon,
  Clock,
  Hash,
  ArrowRight,
  Info
} from 'lucide-react';

const BANGLADESH_DISTRICTS = [
  'Bagerhat', 'Bandarban', 'Barguna', 'Barishal', 'Bhola', 'Bogra', 'Brahmanbaria', 'Chandpur', 
  'Chittagong', 'Chuadanga', 'Comilla', 'Cox\'s Bazar', 'Dhaka', 'Dinajpur', 'Faridpur', 'Feni', 
  'Gaibandha', 'Gazipur', 'Gopalganj', 'Habiganj', 'Jamalpur', 'Jessore', 'Jhalokati', 'Jhenaidah', 
  'Joypurhat', 'Khagrachhari', 'Khulna', 'Kishoreganj', 'Kurigram', 'Kushtia', 'Lakshmipur', 'Lalmonirhat', 
  'Madaripur', 'Magura', 'Manikganj', 'Meherpur', 'Moulvibazar', 'Munshiganj', 'Mymensingh', 'Naogaon', 
  'Narail', 'Narayanganj', 'Narsingdi', 'Natore', 'Nawabganj', 'Netrokona', 'Nilphamari', 'Noakhali', 
  'Pabna', 'Panchagarh', 'Patuakhali', 'Pirojpur', 'Rajbari', 'Rajshahi', 'Rangamati', 'Rangpur', 
  'Satkhira', 'Shariatpur', 'Sherpur', 'Sirajganj', 'Sunamganj', 'Sylhet', 'Tangail', 'Thakurgaon'
];

const BUS_TYPES = [
  'Sleeper Class AC Coach (28 berths)',
  'Business / VIP Class AC Coach (28 seats)',
  'Premium Recliner AC Coach (31 seats)',
  'Standard Executive AC Coach (40 seats)',
  'BRTC Double-Decker Highway Bus (46–70 seats)',
  'Standard Non-AC Highway Coach (52 seats)',
  'Economy / High-Density Non-AC Bus (55 seats)',
  'Mini / Hilly Route Regional Coach (30 seats)'
];

const INITIAL_FORM_STATE = {
  name: '',
  busNumber: '',
  from: '',
  to: '',
  busType: '',
  fare: '',
  seats: '',
  arrivalTime: '',
  departureTime: '',
  estimatedHours: '',
  images: []
};

export default function Admin({ user = {}, activeTab = 'home' }) {
  const [buses, setBuses] = useState(() => {
    const savedBuses = localStorage.getItem('app_buses');
    return savedBuses ? JSON.parse(savedBuses) : [
      { 
        id: 101, 
        name: 'Green Line Paribahan', 
        busNumber: 'GL-501',
        from: 'Dhaka',
        to: 'Cox\'s Bazar',
        route: 'Dhaka to Cox\'s Bazar', 
        fare: '1500 BDT', 
        seats: 28,
        busType: 'Sleeper Class AC Coach (28 berths)',
        arrivalTime: '21:30',
        departureTime: '22:00',
        estimatedHours: '10 hrs',
        images: []
      },
      { 
        id: 102, 
        name: 'Ena Transport', 
        busNumber: 'ENA-302',
        from: 'Dhaka',
        to: 'Sylhet',
        route: 'Dhaka to Sylhet', 
        fare: '800 BDT', 
        seats: 52,
        busType: 'Standard Non-AC Highway Coach (52 seats)',
        arrivalTime: '07:00',
        departureTime: '07:30',
        estimatedHours: '6 hrs',
        images: []
      }
    ];
  });

  const [registeredUsers, setRegisteredUsers] = useState([]);
  const [ticketSales, setTicketSales] = useState(() => {
    const savedTickets = localStorage.getItem('app_tickets');
    return savedTickets ? JSON.parse(savedTickets) : [];
  });

  const [selectedUserHistory, setSelectedUserHistory] = useState(null);
  const [selectedBusDetails, setSelectedBusDetails] = useState(null);

  const [profileImage, setProfileImage] = useState(() => {
    return localStorage.getItem(`avatar_${user?.emailOrPhone || 'admin'}`) || null;
  });

  useEffect(() => {
    const syncData = () => {
      const loadedUsers = JSON.parse(localStorage.getItem('app_users') || '[]');
      const loadedTickets = JSON.parse(localStorage.getItem('app_tickets') || '[]');
      setRegisteredUsers(loadedUsers);
      setTicketSales(loadedTickets);
    };

    syncData();
    window.addEventListener('storage', syncData);
    return () => window.removeEventListener('storage', syncData);
  }, [activeTab]);

  useEffect(() => {
    localStorage.setItem('app_buses', JSON.stringify(buses));
  }, [buses]);

  const totalTicketsSold = ticketSales.length;
  const totalRevenue = ticketSales.reduce((acc, item) => {
    const price = typeof item.fare === 'number' 
      ? item.fare 
      : parseInt(String(item.fare || '0').replace(/[^0-9]/g, ''), 10) || 0;
    return acc + price;
  }, 0);

  const [passwordData, setPasswordData] = useState({ current: '', new: '', confirm: '' });
  const [pwdMsg, setPwdMsg] = useState({ type: '', text: '' });

  const [isModalOpen, setIsModalOpen] = useState(false);
  const [newBus, setNewBus] = useState(INITIAL_FORM_STATE);

  const handleCloseModal = () => {
    setIsModalOpen(false);
    setNewBus(INITIAL_FORM_STATE);
  };

  const handleBusImagesUpload = (e) => {
    const files = Array.from(e.target.files);
    if (!files.length) return;

    const filePromises = files.map((file) => {
      return new Promise((resolve) => {
        const reader = new FileReader();
        reader.onloadend = () => resolve(reader.result);
        reader.readAsDataURL(file);
      });
    });

    Promise.all(filePromises).then((base64Images) => {
      setNewBus((prev) => ({
        ...prev,
        images: [...prev.images, ...base64Images]
      }));
    });
  };

  const handleRemoveImage = (indexToRemove) => {
    setNewBus((prev) => ({
      ...prev,
      images: prev.images.filter((_, idx) => idx !== indexToRemove)
    }));
  };

  const handleImageChange = (e) => {
    const file = e.target.files[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        const base64Image = reader.result;
        setProfileImage(base64Image);
        localStorage.setItem(`avatar_${user?.emailOrPhone || 'admin'}`, base64Image);
      };
      reader.readAsDataURL(file);
    }
  };

  const handlePasswordSubmit = (e) => {
    e.preventDefault();
    if (!passwordData.current || !passwordData.new || !passwordData.confirm) {
      setPwdMsg({ type: 'error', text: 'Please fill in all password fields.' });
      return;
    }
    if (passwordData.new !== passwordData.confirm) {
      setPwdMsg({ type: 'error', text: 'New passwords do not match!' });
      return;
    }
    if (passwordData.new.length < 6) {
      setPwdMsg({ type: 'error', text: 'Password must be at least 6 characters.' });
      return;
    }

    setPwdMsg({ type: 'success', text: 'Password updated successfully!' });
    setPasswordData({ current: '', new: '', confirm: '' });
  };

  const handleDeleteBus = (e, id) => {
    e.stopPropagation();
    setBuses(buses.filter((bus) => bus.id !== id));
  };

  const handleAddBusSubmit = (e) => {
    e.preventDefault();
    if (!newBus.name || !newBus.busNumber || !newBus.fare || !newBus.from || !newBus.to || !newBus.busType) {
      alert('Please fill out all required route details!');
      return;
    }

    const createdBus = {
      id: Math.floor(100 + Math.random() * 900),
      name: newBus.name,
      busNumber: newBus.busNumber,
      from: newBus.from,
      to: newBus.to,
      route: `${newBus.from} to ${newBus.to}`,
      fare: newBus.fare.includes('BDT') ? newBus.fare : `${newBus.fare} BDT`,
      seats: Number(newBus.seats) || 36,
      busType: newBus.busType,
      arrivalTime: newBus.arrivalTime || 'N/A',
      departureTime: newBus.departureTime || 'N/A',
      estimatedHours: newBus.estimatedHours ? `${newBus.estimatedHours} hrs` : 'N/A',
      images: newBus.images
    };

    setBuses([...buses, createdBus]);
    handleCloseModal();
  };

  return (
    <div style={styles.container}>
      {/* 1. HOME TAB */}
      {activeTab === 'home' && (
        <>
          <div style={styles.headerRow}>
            <div>
              <h2 style={styles.title}>Admin Panel ({user?.name || 'Administrator'})</h2>
              <p style={styles.subText}>System Overview & Fleet Management</p>
            </div>
            <button style={styles.addBtn} onClick={() => { setNewBus(INITIAL_FORM_STATE); setIsModalOpen(true); }}>
              <PlusCircle size={18} /> Add Bus Route
            </button>
          </div>

          {/* Key Metrics Grid */}
          <div style={styles.statsGrid}>
            <div style={styles.statCard}>
              <div style={styles.statIconWrapper}><Bus size={22} color="#ea580c" /></div>
              <div>
                <h3 style={styles.statValue}>{buses.length} Active Buses</h3>
                <span style={styles.statLabel}>Operational Fleets</span>
              </div>
            </div>

            <div style={styles.statCard}>
              <div style={styles.statIconWrapper}><Users size={22} color="#ea580c" /></div>
              <div>
                <h3 style={styles.statValue}>{registeredUsers.length} Real Users</h3>
                <span style={styles.statLabel}>Registered Accounts</span>
              </div>
            </div>

            <div style={styles.statCard}>
              <div style={styles.statIconWrapper}><Ticket size={22} color="#ea580c" /></div>
              <div>
                <h3 style={styles.statValue}>{totalTicketsSold} Tickets</h3>
                <span style={styles.statLabel}>Sold Today</span>
              </div>
            </div>

            <div style={styles.statCard}>
              <div style={styles.statIconWrapper}><TrendingUp size={22} color="#ea580c" /></div>
              <div>
                <h3 style={styles.statValue}>৳ {totalRevenue.toLocaleString()}</h3>
                <span style={styles.statLabel}>Total Revenue</span>
              </div>
            </div>
          </div>

          {/* ACTIVE ROUTE BOXES (GRID VIEW) */}
          <div style={styles.card}>
            <div style={styles.tableHeader}>
              <h3 style={styles.cardTitle}>Active Bus Routes</h3>
              <span style={styles.countBadge}>{buses.length} Routes Available</span>
            </div>

            {buses.length === 0 ? (
              <div style={styles.emptyBox}>
                <Bus size={36} color="#71717a" />
                <p>No bus routes added yet. Click "+ Add Bus Route" above to create one.</p>
              </div>
            ) : (
              <div style={styles.routeGrid}>
                {buses.map((bus) => (
                  <div 
                    key={bus.id} 
                    style={styles.routeBox} 
                    onClick={() => setSelectedBusDetails(bus)}
                  >
                    {/* Card Top: Bus Image */}
                    <div style={styles.boxImageArea}>
                      {bus.images && bus.images.length > 0 ? (
                        <img src={bus.images[0]} alt={bus.name} style={styles.boxImg} />
                      ) : (
                        <div style={styles.boxImgPlaceholder}>
                          <Bus size={40} color="#52525b" />
                          <span>No Image Attached</span>
                        </div>
                      )}
                      <span style={styles.boxIdTag}>#{bus.id}</span>
                      <button 
                        style={styles.boxDeleteBtn} 
                        title="Delete Route" 
                        onClick={(e) => handleDeleteBus(e, bus.id)}
                      >
                        <Trash2 size={15} />
                      </button>
                    </div>

                    {/* Card Content: Route & Fare */}
                    <div style={styles.boxBody}>
                      <div style={styles.operatorName}>{bus.name}</div>
                      
                      <div style={styles.boxRouteTitle}>
                        {bus.route || `${bus.from} to ${bus.to}`}
                      </div>

                      <div style={styles.boxFooter}>
                        <div>
                          <span style={styles.fareLabel}>Ticket Price</span>
                          <div style={styles.boxFare}>{bus.fare}</div>
                        </div>
                        <span style={styles.viewDetailsHint}>
                          View Details <ArrowRight size={14} />
                        </span>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
        </>
      )}

      {/* 2. PROFILE TAB */}
      {activeTab === 'profile' && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '24px' }}>
          <div style={styles.card}>
            <div style={styles.flexTitle}>
              <UserIcon size={24} color="#ea580c" /> 
              <h2 style={styles.cardTitle}>Administrator Account</h2>
            </div>

            <div style={styles.profileSection}>
              <div style={styles.avatarContainer}>
                <div style={styles.avatarCircle}>
                  {profileImage ? (
                    <img src={profileImage} alt="Profile" style={styles.avatarImg} />
                  ) : (
                    <UserIcon size={48} color="#a1a1aa" />
                  )}
                </div>
                <label htmlFor="photo-upload" style={styles.cameraBtn} title="Upload Permanent Photo">
                  <Camera size={14} color="#ffffff" />
                  <input 
                    id="photo-upload" 
                    type="file" 
                    accept="image/*" 
                    onChange={handleImageChange} 
                    style={{ display: 'none' }} 
                  />
                </label>
              </div>

              <div style={styles.infoGroup}>
                <div style={styles.profileRow}>
                  <span style={styles.profileLabel}><UserIcon size={16} /> Name:</span>
                  <span style={styles.profileValue}>{user?.name || 'Super Administrator'}</span>
                </div>
                <div style={styles.profileRow}>
                  <span style={styles.profileLabel}><Mail size={16} /> Email:</span>
                  <span style={styles.profileValue}>{user?.emailOrPhone || 'admin@onlinebus.bd'}</span>
                </div>
                <div style={styles.profileRow}>
                  <span style={styles.profileLabel}><Phone size={16} /> Phone:</span>
                  <span style={styles.profileValue}>{user?.phone || '+880 1700-000000'}</span>
                </div>
                <div style={styles.profileRow}>
                  <span style={styles.profileLabel}><Shield size={16} /> Assigned Role:</span>
                  <span style={styles.roleBadge}>Super Admin Portal</span>
                </div>
              </div>
            </div>
          </div>

          <div style={styles.card}>
            <div style={styles.tableHeader}>
              <div style={styles.flexTitle}>
                <UserCheck size={22} color="#ea580c" />
                <h3 style={styles.cardTitle}>Real Registered Users</h3>
              </div>
              <span style={styles.countBadge}>{registeredUsers.length} Real Signups</span>
            </div>

            {registeredUsers.length === 0 ? (
              <div style={styles.emptyBox}>
                <Users size={32} color="#71717a" />
                <p>No registered users found yet.</p>
              </div>
            ) : (
              <div style={{ overflowX: 'auto' }}>
                <table style={styles.table}>
                  <thead>
                    <tr>
                      <th style={styles.th}>User ID</th>
                      <th style={styles.th}>Full Name</th>
                      <th style={styles.th}>Email / Username</th>
                      <th style={styles.th}>Phone</th>
                      <th style={styles.th}>Joined Date</th>
                      <th style={styles.th}>Role</th>
                      <th style={{ ...styles.th, textAlign: 'center' }}>User History</th>
                    </tr>
                  </thead>
                  <tbody>
                    {registeredUsers.map((u) => (
                      <tr key={u.id} style={styles.tr}>
                        <td style={styles.td}><span style={styles.userIdBadge}>{u.id}</span></td>
                        <td style={{ ...styles.td, fontWeight: '600', color: '#f4f4f5' }}>{u.name}</td>
                        <td style={styles.td}>{u.email}</td>
                        <td style={styles.td}>{u.phone || 'N/A'}</td>
                        <td style={styles.td}>{u.joined || 'Recent'}</td>
                        <td style={styles.td}>
                          <span style={u.role === 'admin' ? styles.roleBadgeAdmin : styles.activeBadge}>
                            {u.role || 'Passenger'}
                          </span>
                        </td>
                        <td style={{ ...styles.td, textAlign: 'center' }}>
                          <button 
                            style={styles.historyBtn} 
                            onClick={() => setSelectedUserHistory(u)}
                          >
                            <History size={14} /> View History
                          </button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            )}
          </div>

          <div style={styles.card}>
            <div style={styles.flexTitle}>
              <Lock size={22} color="#ea580c" />
              <h3 style={styles.cardTitle}>Change Password</h3>
            </div>

            {pwdMsg.text && (
              <div style={pwdMsg.type === 'error' ? styles.errorAlert : styles.successAlert}>
                {pwdMsg.text}
              </div>
            )}

            <form onSubmit={handlePasswordSubmit} style={styles.passwordForm}>
              <div style={styles.formRow}>
                <div style={{ ...styles.fieldGroup, flex: 1 }}>
                  <label style={styles.modalLabel}>Current Password</label>
                  <input
                    type="password"
                    placeholder="••••••••"
                    value={passwordData.current}
                    onChange={(e) => setPasswordData({ ...passwordData, current: e.target.value })}
                    style={styles.modalInput}
                  />
                </div>
                <div style={{ ...styles.fieldGroup, flex: 1 }}>
                  <label style={styles.modalLabel}>New Password</label>
                  <input
                    type="password"
                    placeholder="••••••••"
                    value={passwordData.new}
                    onChange={(e) => setPasswordData({ ...passwordData, new: e.target.value })}
                    style={styles.modalInput}
                  />
                </div>
                <div style={{ ...styles.fieldGroup, flex: 1 }}>
                  <label style={styles.modalLabel}>Confirm New Password</label>
                  <input
                    type="password"
                    placeholder="••••••••"
                    value={passwordData.confirm}
                    onChange={(e) => setPasswordData({ ...passwordData, confirm: e.target.value })}
                    style={styles.modalInput}
                  />
                </div>
              </div>

              <button type="submit" style={styles.savePwdBtn}>Update Password</button>
            </form>
          </div>
        </div>
      )}

      {/* 3. PAYMENT TAB */}
      {activeTab === 'payment' && (
        <div style={{ display: 'flex', flexDirection: 'column', gap: '24px' }}>
          <div style={styles.card}>
            <div style={styles.flexTitle}>
              <CreditCard size={24} color="#ea580c" /> 
              <h2 style={styles.cardTitle}>Payment Gateway Settlement</h2>
            </div>
            <p style={{ color: '#a1a1aa', marginBottom: '20px' }}>
              Configure merchant credentials and live webhook endpoints for payment clearance in Bangladesh.
            </p>

            <div style={styles.gatewayGrid}>
              {['bKash Direct API', 'Nagad Merchant', 'Rocket Express', 'SSLCommerz Gateway'].map((gw, index) => (
                <div key={index} style={styles.gatewayCard}>
                  <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
                    <div style={{ display: 'flex', alignItems: 'center', gap: '8px', color: '#f4f4f5', fontWeight: '600' }}>
                      <DollarSign size={18} color="#ea580c" /> {gw}
                    </div>
                    <span style={styles.connectedBadge}>Active</span>
                  </div>
                  <div style={styles.keyRow}>
                    <Key size={14} color="#71717a" />
                    <span style={{ fontSize: '0.8rem', color: '#71717a' }}>Merchant Key: ••••••••••••8892</span>
                  </div>
                </div>
              ))}
            </div>
          </div>
        </div>
      )}

      {/* ROUTE DETAILS MODAL (OPENED WHEN CLICKING A BOX) */}
      {selectedBusDetails && (
        <div style={styles.modalOverlay} onClick={() => setSelectedBusDetails(null)}>
          <div style={{ ...styles.modalContent, maxWidth: '600px' }} onClick={(e) => e.stopPropagation()}>
            <div style={styles.modalHeader}>
              <div>
                <h3 style={{ margin: 0, color: '#ea580c', fontSize: '1.3rem' }}>
                  {selectedBusDetails.name}
                </h3>
                <span style={{ fontSize: '0.85rem', color: '#a1a1aa' }}>
                  Coach No: {selectedBusDetails.busNumber || 'N/A'} | ID: #{selectedBusDetails.id}
                </span>
              </div>
              <button style={styles.closeBtn} onClick={() => setSelectedBusDetails(null)}>
                <X size={20} />
              </button>
            </div>

            {/* Modal Pictures Preview */}
            {selectedBusDetails.images && selectedBusDetails.images.length > 0 ? (
              <div style={styles.modalGallery}>
                {selectedBusDetails.images.map((img, i) => (
                  <img key={i} src={img} alt="Bus detail" style={styles.modalDetailImg} />
                ))}
              </div>
            ) : (
              <div style={styles.modalImgPlaceholder}>
                <Bus size={48} color="#71717a" />
                <p style={{ margin: '8px 0 0 0', color: '#71717a', fontSize: '0.85rem' }}>No photo available for this vehicle</p>
              </div>
            )}

            {/* Detailed Info Grid */}
            <div style={styles.detailGrid}>
              <div style={styles.detailCard}>
                <span style={styles.detailLabel}>Route</span>
                <span style={styles.detailValue}>{selectedBusDetails.route || `${selectedBusDetails.from} to ${selectedBusDetails.to}`}</span>
              </div>

              <div style={styles.detailCard}>
                <span style={styles.detailLabel}>Bus Type</span>
                <span style={{ ...styles.detailValue, color: '#38bdf8' }}>{selectedBusDetails.busType || 'Standard'}</span>
              </div>

              <div style={styles.detailCard}>
                <span style={styles.detailLabel}>Ticket Fare</span>
                <span style={{ ...styles.detailValue, color: '#22c55e', fontSize: '1.1rem' }}>{selectedBusDetails.fare}</span>
              </div>

              <div style={styles.detailCard}>
                <span style={styles.detailLabel}>Total Capacity</span>
                <span style={styles.detailValue}>{selectedBusDetails.seats} Seats</span>
              </div>

              <div style={styles.detailCard}>
                <span style={styles.detailLabel}>Departure Time</span>
                <span style={styles.detailValue}>{selectedBusDetails.departureTime || 'N/A'}</span>
              </div>

              <div style={styles.detailCard}>
                <span style={styles.detailLabel}>Arrival Time</span>
                <span style={styles.detailValue}>{selectedBusDetails.arrivalTime || 'N/A'}</span>
              </div>

              <div style={{ ...styles.detailCard, gridColumn: 'span 2' }}>
                <span style={styles.detailLabel}>Estimated Travel Duration</span>
                <span style={styles.detailValue}>{selectedBusDetails.estimatedHours || 'N/A'}</span>
              </div>
            </div>

            <div style={{ display: 'flex', justifyContent: 'flex-end', marginTop: '20px' }}>
              <button style={styles.cancelBtn} onClick={() => setSelectedBusDetails(null)}>
                Close Details
              </button>
            </div>
          </div>
        </div>
      )}

      {/* USER HISTORY MODAL */}
      {selectedUserHistory && (
        <div style={styles.modalOverlay} onClick={() => setSelectedUserHistory(null)}>
          <div style={styles.modalContent} onClick={(e) => e.stopPropagation()}>
            <div style={styles.modalHeader}>
              <div>
                <h3>User History: {selectedUserHistory.name}</h3>
                <span style={{ fontSize: '0.8rem', color: '#a1a1aa' }}>ID: {selectedUserHistory.id} | Email: {selectedUserHistory.email}</span>
              </div>
              <button style={styles.closeBtn} onClick={() => setSelectedUserHistory(null)}>
                <X size={20} />
              </button>
            </div>

            <div style={{ marginTop: '16px' }}>
              <h4 style={{ color: '#ea580c', margin: '0 0 12px 0' }}>Activity & Booking Logs</h4>
              {selectedUserHistory.history && selectedUserHistory.history.length > 0 ? (
                <div style={{ display: 'flex', flexDirection: 'column', gap: '8px' }}>
                  {selectedUserHistory.history.map((log, idx) => (
                    <div key={idx} style={styles.historyCard}>
                      <div style={{ fontWeight: '600', color: '#f4f4f5' }}>{log.type}</div>
                      <div style={{ fontSize: '0.8rem', color: '#a1a1aa' }}>{log.details}</div>
                      <div style={{ fontSize: '0.75rem', color: '#ea580c', marginTop: '4px' }}>{log.date}</div>
                    </div>
                  ))}
                </div>
              ) : (
                <p style={{ color: '#71717a', fontSize: '0.9rem' }}>No ticket purchases or bookings recorded for this user yet.</p>
              )}
            </div>
          </div>
        </div>
      )}

      {/* ADD BUS ROUTE MODAL */}
      {isModalOpen && (
        <div style={styles.modalOverlay}>
          <div style={{ ...styles.modalContent, maxWidth: '650px', maxHeight: '90vh', overflowY: 'auto' }}>
            <div style={styles.modalHeader}>
              <div>
                <h3 style={{ margin: 0, color: '#f4f4f5' }}>Add New Bus Route</h3>
                <span style={{ fontSize: '0.8rem', color: '#a1a1aa' }}>Fill in full route schedules and details</span>
              </div>
              <button style={styles.closeBtn} onClick={handleCloseModal}><X size={20} /></button>
            </div>

            <form onSubmit={handleAddBusSubmit} style={styles.modalForm}>
              {/* Upload Bus Pictures */}
              <div style={styles.fieldGroup}>
                <label style={styles.modalLabel}>
                  <ImageIcon size={14} color="#ea580c" /> Upload Bus Pictures (One or Many)
                </label>
                <div style={styles.uploadBox}>
                  <input
                    type="file"
                    accept="image/*"
                    multiple
                    onChange={handleBusImagesUpload}
                    id="bus-images-input"
                    style={{ display: 'none' }}
                  />
                  <label htmlFor="bus-images-input" style={styles.uploadLabelBtn}>
                    <PlusCircle size={16} /> Choose Bus Photos
                  </label>

                  {newBus.images.length > 0 && (
                    <div style={styles.imagePreviewRow}>
                      {newBus.images.map((img, idx) => (
                        <div key={idx} style={styles.imgBadgeWrapper}>
                          <img src={img} alt={`Bus preview ${idx}`} style={styles.previewThumb} />
                          <button
                            type="button"
                            style={styles.removeImgBtn}
                            onClick={() => handleRemoveImage(idx)}
                          >
                            <X size={12} />
                          </button>
                        </div>
                      ))}
                    </div>
                  )}
                </div>
              </div>

              {/* Operator & Bus Number */}
              <div style={styles.formRow}>
                <div style={{ ...styles.fieldGroup, flex: 1.5 }}>
                  <label style={styles.modalLabel}>Operator / Bus Name</label>
                  <input
                    type="text"
                    placeholder="e.g. Shyamoli NR Travels"
                    value={newBus.name}
                    onChange={(e) => setNewBus({ ...newBus, name: e.target.value })}
                    style={styles.modalInput}
                    required
                  />
                </div>

                <div style={{ ...styles.fieldGroup, flex: 1 }}>
                  <label style={styles.modalLabel}>
                    <Hash size={13} color="#ea580c" /> Bus Number / Coach No
                  </label>
                  <input
                    type="text"
                    placeholder="e.g. DHAKA-METRO-11"
                    value={newBus.busNumber}
                    onChange={(e) => setNewBus({ ...newBus, busNumber: e.target.value })}
                    style={styles.modalInput}
                    required
                  />
                </div>
              </div>

              {/* Bus Type */}
              <div style={styles.fieldGroup}>
                <label style={styles.modalLabel}>Bus Type</label>
                <select
                  value={newBus.busType}
                  onChange={(e) => setNewBus({ ...newBus, busType: e.target.value })}
                  style={styles.modalSelect}
                  required
                >
                  <option value="" disabled>-- Select Bus Type --</option>
                  {BUS_TYPES.map((type, idx) => (
                    <option key={idx} value={type}>{type}</option>
                  ))}
                </select>
              </div>

              {/* Route From & To */}
              <div style={styles.formRow}>
                <div style={{ ...styles.fieldGroup, flex: 1 }}>
                  <label style={styles.modalLabel}>Route From (Departure District)</label>
                  <select
                    value={newBus.from}
                    onChange={(e) => setNewBus({ ...newBus, from: e.target.value })}
                    style={styles.modalSelect}
                    required
                  >
                    <option value="" disabled>-- Select District --</option>
                    {BANGLADESH_DISTRICTS.map((dist) => (
                      <option key={`from-${dist}`} value={dist}>{dist}</option>
                    ))}
                  </select>
                </div>

                <div style={{ ...styles.fieldGroup, flex: 1 }}>
                  <label style={styles.modalLabel}>Route To (Arrival District)</label>
                  <select
                    value={newBus.to}
                    onChange={(e) => setNewBus({ ...newBus, to: e.target.value })}
                    style={styles.modalSelect}
                    required
                  >
                    <option value="" disabled>-- Select District --</option>
                    {BANGLADESH_DISTRICTS.map((dist) => (
                      <option key={`to-${dist}`} value={dist}>{dist}</option>
                    ))}
                  </select>
                </div>
              </div>

              {/* Fare & Seats */}
              <div style={styles.formRow}>
                <div style={{ ...styles.fieldGroup, flex: 1 }}>
                  <label style={styles.modalLabel}>Ticket Fare (BDT)</label>
                  <input
                    type="text"
                    placeholder="e.g. 1100"
                    value={newBus.fare}
                    onChange={(e) => setNewBus({ ...newBus, fare: e.target.value })}
                    style={styles.modalInput}
                    required
                  />
                </div>

                <div style={{ ...styles.fieldGroup, flex: 1 }}>
                  <label style={styles.modalLabel}>Total Seats</label>
                  <input
                    type="number"
                    placeholder="e.g. 40"
                    value={newBus.seats}
                    onChange={(e) => setNewBus({ ...newBus, seats: e.target.value })}
                    style={styles.modalInput}
                    min="1"
                    max="100"
                    required
                  />
                </div>
              </div>

              {/* Departure, Arrival & Hours */}
              <div style={styles.formRow}>
                <div style={{ ...styles.fieldGroup, flex: 1 }}>
                  <label style={styles.modalLabel}><Clock size={12} /> Departure Time</label>
                  <input
                    type="time"
                    value={newBus.departureTime}
                    onChange={(e) => setNewBus({ ...newBus, departureTime: e.target.value })}
                    style={styles.modalInput}
                    required
                  />
                </div>

                <div style={{ ...styles.fieldGroup, flex: 1 }}>
                  <label style={styles.modalLabel}><Clock size={12} /> Arrival Time</label>
                  <input
                    type="time"
                    value={newBus.arrivalTime}
                    onChange={(e) => setNewBus({ ...newBus, arrivalTime: e.target.value })}
                    style={styles.modalInput}
                    required
                  />
                </div>

                <div style={{ ...styles.fieldGroup, flex: 1 }}>
                  <label style={styles.modalLabel}>Est. Duration (Hours)</label>
                  <input
                    type="number"
                    step="0.5"
                    placeholder="e.g. 6.5"
                    value={newBus.estimatedHours}
                    onChange={(e) => setNewBus({ ...newBus, estimatedHours: e.target.value })}
                    style={styles.modalInput}
                    required
                  />
                </div>
              </div>

              <div style={styles.modalActions}>
                <button type="button" style={styles.cancelBtn} onClick={handleCloseModal}>Cancel</button>
                <button type="submit" style={styles.submitModalBtn}>Save Route</button>
              </div>
            </form>
          </div>
        </div>
      )}
    </div>
  );
}

